int licznik = 0;
int liczba = 0;
int minimum, maksimum, jasnosc;

void Znak(int iNumer) {
  // Sterowanie dodatkowym pinem (np. kropka)
  digitalWrite(8, ((iNumer == 0) || (iNumer == 1) || (iNumer == 7)) ? HIGH : LOW);

  // Wzorce bitowe dla portu D (piny 0-7)
  switch (iNumer) {
    case 0: PORTD = 0b00000000; break;
    case 1: PORTD = 0b11100100; break;
    case 2: PORTD = 0b01001001; break;
    case 3: PORTD = 0b01100001; break;
    case 4: PORTD = 0b00110101; break;
    case 5: PORTD = 0b00100111; break;
    case 6: PORTD = 0b00000111; break;
    case 7: PORTD = 0b11100000; break;
    case 8: PORTD = 0b00000001; break;
    case 9: PORTD = 0b00100001; break;
    default: PORTD = 0b11011000; break;
  }
}

void setup() {
  // Ustawienie pinów 2 do 8 jako wyjścia dla segmentów
  for (int i = 2; i <= 8; i++) {
    pinMode(i, OUTPUT);
  }
  // Piny sterujące wspólnymi wyprowadzeniami cyfr (wspólna anoda/katoda)
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {
  // --- CYFRA 1 (Jedności) ---
  digitalWrite(10, HIGH); // Wyłącz drugą cyfrę
  digitalWrite(11, HIGH); // Wygaszenie (wyłącz też pierwszą przed zmianą portu)
  Znak(liczba % 10);      // Wyślij wzorzec dla jedności
  digitalWrite(11, LOW);  // Włącz pierwszą cyfrę
  delay(3);               // Krótkie opóźnienie na wyświetlenie

  // --- CYFRA 2 (Dziesiątki) ---
  digitalWrite(11, HIGH); // Wyłącz pierwszą cyfrę
  digitalWrite(10, HIGH); // Wygaszenie (wyłącz też drugą przed zmianą portu)
  Znak((liczba / 10) % 10); // Wyślij wzorzec dla dziesiątek
  digitalWrite(10, LOW);  // Włącz drugą cyfrę
  delay(3);               // Krótkie opóźnienie na wyświetlenie

  // Aktualizacja pomiaru światła co określony czas
  if (licznik++ > 50) { 
    jasnosc = analogRead(A0);
    if (minimum > jasnosc) minimum = jasnosc;
    if (maksimum < jasnosc) maksimum = jasnosc;

    if (minimum != maksimum) {
      jasnosc = 99 * (jasnosc - minimum) / (maksimum - minimum);
    } else {
      jasnosc = 0;
    }

    liczba = jasnosc;
    licznik = 0;
  }
}
